<?php

declare(strict_types=1);

namespace OpenTelemetry\Contrib\Ci\Tests;

use OpenTelemetry\Contrib\Ci\Badges;
use OpenTelemetry\Contrib\Ci\Project;
use PHPUnit\Framework\TestCase;

/**
 * Each project's CI badge, the generated project list in the root
 * README, and the problems --check reports when either is missing or
 * stale.
 */
final class BadgesTest extends TestCase
{
    private const ROOT_README = <<<'MD'
        # Contrib

        <!-- Generated by .github/ci/matrix.php --generate. Do not edit. -->
        <!-- End of generated project list. -->

        ## Usage

        MD;

    public function test_links_a_badge_to_the_projects_runs_on_main(): void
    {
        $this->assertSame(
            '[![CI](https://github.com/open-telemetry/opentelemetry-php-contrib/actions/workflows/project-instrumentation-laravel.yml/badge.svg?branch=main)](https://github.com/open-telemetry/opentelemetry-php-contrib/actions/workflows/project-instrumentation-laravel.yml?query=branch%3Amain)',
            Badges::badge(self::project('Instrumentation/Laravel')),
        );
    }

    public function test_lists_each_project_with_its_badge_sorted_by_path_between_the_markers(): void
    {
        $aws = Badges::badge(self::project('Aws'));
        $symfony = Badges::badge(self::project('Symfony'));

        $this->assertSame(<<<MD
            # Contrib

            <!-- Generated by .github/ci/matrix.php --generate. Do not edit. -->
            | Project | CI |
            |---|---|
            | [Aws](src/Aws) | $aws |
            | [Symfony](src/Symfony) | $symfony |
            <!-- End of generated project list. -->

            ## Usage

            MD, Badges::updateRoot(self::ROOT_README, self::projects('Symfony', 'Aws')));
    }

    public function test_replaces_a_stale_list(): void
    {
        $stale = (string) Badges::updateRoot(self::ROOT_README, self::projects('Aws', 'Gone'));

        $this->assertSame(
            Badges::updateRoot(self::ROOT_README, self::projects('Aws')),
            Badges::updateRoot($stale, self::projects('Aws')),
        );
    }

    public function test_cannot_update_a_readme_without_both_markers(): void
    {
        $this->assertNull(Badges::updateRoot("# Contrib\n", self::projects('Aws')));
        $this->assertNull(Badges::updateRoot("<!-- End of generated project list. -->\n<!-- Generated by .github/ci/matrix.php --generate. Do not edit. -->\n", self::projects('Aws')));
    }

    public function test_accepts_current_readmes(): void
    {
        $projects = self::projects('Aws', 'Symfony');

        $this->assertSame([], Badges::problems(
            $projects,
            self::readmes($projects),
            (string) Badges::updateRoot(self::ROOT_README, $projects),
        ));
    }

    public function test_reports_a_project_readme_without_its_badge_printing_the_line_to_add(): void
    {
        $projects = self::projects('Aws', 'Symfony');
        $readmes = self::readmes($projects);
        $readmes['src/Symfony/README.md'] = "# Symfony\n";
        unset($readmes['src/Aws/README.md']);
        $badge = fn (string $name) => Badges::badge(self::project($name));

        $this->assertSame(
            [
                '::error file=src/Aws/README.md::src/Aws/README.md has no CI badge. Add this line: ' . $badge('Aws'),
                '::error file=src/Symfony/README.md::src/Symfony/README.md has no CI badge. Add this line: ' . $badge('Symfony'),
            ],
            Badges::problems($projects, $readmes, (string) Badges::updateRoot(self::ROOT_README, $projects)),
        );
    }

    public function test_reports_a_stale_root_list(): void
    {
        $projects = self::projects('Aws', 'Symfony');

        $this->assertSame(
            ['::error file=README.md::README.md\'s project list differs from what matrix.php generates. Run make ci-generate.'],
            Badges::problems($projects, self::readmes($projects), self::ROOT_README),
        );
    }

    public function test_reports_a_root_readme_without_the_markers(): void
    {
        $projects = self::projects('Aws');

        $this->assertSame(
            ['::error file=README.md::README.md has no generated project list. Add the lines <!-- Generated by .github/ci/matrix.php --generate. Do not edit. --> and <!-- End of generated project list. -->, then run make ci-generate.'],
            Badges::problems($projects, self::readmes($projects), "# Contrib\n"),
        );
    }

    /**
     * @param list<Project> $projects
     * @return array<string, string>
     */
    private static function readmes(array $projects): array
    {
        $readmes = [];
        foreach ($projects as $project) {
            $readmes["src/$project->name/README.md"] = "# $project->name\n\n" . Badges::badge($project) . "\n";
        }

        return $readmes;
    }

    private static function project(string $name): Project
    {
        return Project::fromComposerJson($name, '{}', true);
    }

    /** @return list<Project> */
    private static function projects(string ...$names): array
    {
        return array_map(self::project(...), array_values($names));
    }
}
